/**
 * @module core/agent/tools/shared
 *
 * Plumbing shared by every tool: progress callbacks, ledger recording, and
 * turning failures into a readable error result (so one bad call doesn't crash
 * the whole turn — the model can say it couldn't get that data).
 */
import { formatBoundaryMessage, describeUnknownError } from "../../errors/boundaryError";
import type { Hub } from "../../domain/hub";
import type { ToolLedger, ToolOutputBase } from "../ledger";

/** Progress hooks the API layer uses to stream "Consulting the ledger for Dallas…". */
export interface ToolCallbacks {
  onToolStart?: (tool: string, input: unknown) => void;
  onToolEnd?: (tool: string, output: unknown) => void;
}

/** What every tool builder receives. */
export interface ToolRuntime {
  ledger: ToolLedger;
  callbacks: ToolCallbacks;
}

/** Error result returned to the model instead of throwing. */
export interface ToolErrorOutput extends ToolOutputBase {
  error: string;
}

/**
 * Runs a tool body with progress callbacks, ledger recording and error capture.
 * @param name - tool name.
 * @param input - validated input.
 * @param runtime - ledger and callbacks.
 * @param body - the tool's work.
 * @returns the tool output (or an error output).
 */
export async function runTool<T extends ToolOutputBase>(
  name: string,
  input: unknown,
  runtime: ToolRuntime,
  body: () => Promise<T> | T,
): Promise<T | ToolErrorOutput> {
  runtime.callbacks.onToolStart?.(name, input);
  let output: T | ToolErrorOutput;
  try {
    output = await body();
  } catch (error) {
    console.error(
      formatBoundaryMessage({ name: "ToolExecutionError", message: describeUnknownError(error), functionName: name, boundary: "llm" }),
    );
    output = { error: describeUnknownError(error), hubIds: [], confidence: null, caveats: [] };
  }
  runtime.ledger.record(name, input, output);
  runtime.callbacks.onToolEnd?.(name, output);
  return output;
}

/** @returns "Dallas, TX". */
export const hubLabel = (hub: Hub): string => `${hub.name}, ${hub.state}`;

/** Rounds for display in tool output (1 decimal). */
export const round1 = (value: number): number => Math.round(value * 10) / 10;

/**
 * @module core/agent/tools/rankHubs
 *
 * `rank_hubs` — "Which Midwest hubs are most exposed to winter disruption?"
 * Ranks are derived from the latest snapshots when called (D54).
 */
import { tool } from "ai";
import { z } from "zod";
import { CENSUS_REGIONS } from "../../domain/hub";
import { GENERAL_CAVEATS, hazardCaveats } from "../../scoring/caveats";
import { weakestConfidence } from "../../scoring/confidence";
import { riskLevelFor } from "../../scoring/overall";
import { rankHubs, type RankMetric } from "../../scoring/ranking";
import { HAZARDS } from "../../scoring/types";
import type { AgentContext } from "../context";
import { hubLabel, runTool, type ToolRuntime } from "./shared";

/**
 * Builds the rank_hubs tool for one request.
 * @param ctx - agent context.
 * @param runtime - ledger and callbacks.
 * @returns the AI SDK tool.
 */
export function buildRankHubsTool(ctx: AgentContext, runtime: ToolRuntime) {
  return tool({
    description:
      "Rank our hubs by overall weather risk or by one hazard, optionally within a US Census region. " +
      "Use for 'which hubs are most/least exposed to X'. Returns each hub's score (0-100), level, and its rank among ALL hubs.",
    inputSchema: z.object({
      metric: z.enum(["overall", ...HAZARDS]).describe("'overall' or a hazard: hurricane, winter, flood, severeStorms, wind, heat."),
      region: z.enum(CENSUS_REGIONS).nullable().describe("US Census region filter, or null for all hubs."),
      order: z.enum(["most", "least"]).describe("'most' = most exposed first."),
      limit: z.number().int().min(1).max(36).describe("How many hubs to return (default 5)."),
    }),
    execute: (input) =>
      runTool("rank_hubs", input, runtime, () => {
        const metric = input.metric as RankMetric;
        const rows = [...ctx.snapshotByHub.values()].map((s) => ({
          hubId: s.hubId,
          region: ctx.hubById.get(s.hubId)!.region,
          scores: { overall: s.overallScore, ...Object.fromEntries(HAZARDS.map((h) => [h, s.hazards[h].score])) },
        }));
        const ranked = rankHubs(rows, { metric, region: input.region ?? undefined, order: input.order, limit: input.limit });
        const results = ranked.map((r) => {
          const snapshot = ctx.snapshotByHub.get(r.hubId)!;
          const hazard = metric === "overall" ? null : snapshot.hazards[metric];
          return {
            hubId: r.hubId,
            hub: hubLabel(ctx.hubById.get(r.hubId)!),
            region: ctx.hubById.get(r.hubId)!.region,
            score: r.score,
            level: metric === "overall" ? snapshot.riskLevel : riskLevelFor(r.score),
            rankAmongAll: r.rankAmongAll,
            totalHubs: r.totalHubs,
            rankInSelection: r.rankInSelection,
            selectionSize: r.selectionSize,
            topHazard: snapshot.topHazard,
            confidence: hazard ? hazard.confidence : snapshot.confidence,
            confidenceReason: hazard ? hazard.confidenceReason : undefined,
          };
        });
        const any = ctx.snapshotByHub.values().next().value!;
        return {
          metric,
          region: input.region,
          order: input.order,
          scoringVersion: any.scoringVersion,
          scoredWindow: any.window,
          results,
          hubIds: results.map((r) => r.hubId),
          confidence: results.length ? weakestConfidence(results.map((r) => r.confidence)) : null,
          caveats: [...GENERAL_CAVEATS, ...(metric === "overall" ? [] : hazardCaveats(metric, ctx.units))],
        };
      }),
  });
}

/**
 * @module core/agent/tools/compareHubs
 *
 * `compare_hubs` — "Compare Miami and Houston in terms of hurricane and flood exposure."
 */
import { tool } from "ai";
import { z } from "zod";
import { GENERAL_CAVEATS, hazardCaveats } from "../../scoring/caveats";
import { weakestConfidence } from "../../scoring/confidence";
import { riskLevelFor } from "../../scoring/overall";
import { competitionRanks } from "../../scoring/ranking";
import { HAZARDS, type Hazard } from "../../scoring/types";
import type { AgentContext } from "../context";
import { hubLabel, runTool, type ToolRuntime } from "./shared";

/**
 * Builds the compare_hubs tool for one request.
 * @param ctx - agent context.
 * @param runtime - ledger and callbacks.
 * @param hubIdSchema - Zod enum of the active hub ids (G12).
 * @returns the AI SDK tool.
 */
export function buildCompareHubsTool(ctx: AgentContext, runtime: ToolRuntime, hubIdSchema: z.ZodEnum) {
  return tool({
    description:
      "Compare 2-5 hubs side by side: overall score, level, rank, and per-hazard scores with both halves " +
      "(observed weather vs FEMA) and confidence. Optionally restrict to some hazards.",
    inputSchema: z.object({
      hubIds: z.array(hubIdSchema).min(2).max(5),
      hazards: z.array(z.enum(HAZARDS)).nullable().describe("Hazards to include, or null for all six."),
    }),
    execute: (input) =>
      runTool("compare_hubs", input, runtime, () => {
        const hazards: Hazard[] = input.hazards?.length ? input.hazards : [...HAZARDS];
        const all = [...ctx.snapshotByHub.values()];
        const overallRanks = competitionRanks(all.map((s) => ({ id: s.hubId, score: s.overallScore })));
        const hazardRanks = Object.fromEntries(
          hazards.map((h) => [h, competitionRanks(all.map((s) => ({ id: s.hubId, score: s.hazards[h].score })))]),
        ) as Record<Hazard, Map<string, number>>;

        const hubs = input.hubIds.map((hubId) => {
          const snapshot = ctx.snapshotByHub.get(hubId);
          if (!snapshot) throw new Error(`No score available for hub "${hubId}".`);
          return {
            hubId,
            hub: hubLabel(ctx.hubById.get(hubId)!),
            overallScore: snapshot.overallScore,
            level: snapshot.riskLevel,
            rankOverall: overallRanks.get(hubId),
            topHazard: snapshot.topHazard,
            hazards: Object.fromEntries(
              hazards.map((h) => {
                const hz = snapshot.hazards[h];
                return [
                  h,
                  {
                    score: hz.score,
                    level: riskLevelFor(hz.score),
                    rankAmongAll: hazardRanks[h].get(hubId),
                    observedScore: hz.observedScore,
                    femaScore: hz.femaScore,
                    confidence: hz.confidence,
                    confidenceReason: hz.confidenceReason,
                  },
                ];
              }),
            ),
          };
        });
        return {
          totalHubs: all.length,
          hubs,
          hubIds: input.hubIds,
          confidence: weakestConfidence(
            input.hubIds.flatMap((id) => hazards.map((h) => ctx.snapshotByHub.get(id)!.hazards[h].confidence)),
          ),
          caveats: [...GENERAL_CAVEATS, ...hazards.flatMap((h) => hazardCaveats(h, ctx.units))],
        };
      }),
  });
}

/**
 * @module core/agent/tools/explainHubScore
 *
 * `explain_hub_score` — "Why is the Dallas hub's weather disruption risk high?"
 * Returns the full, code-built breakdown, including the formula WITH its numbers,
 * so the model can explain without computing anything.
 */
import { tool } from "ai";
import { z } from "zod";
import { GENERAL_CAVEATS, hazardCaveats } from "../../scoring/caveats";
import { HAZARD_WEIGHTS, OVERALL_MIX, RISK_LEVEL_CUTOFFS } from "../../scoring/config";
import { riskLevelFor } from "../../scoring/overall";
import { competitionRanks } from "../../scoring/ranking";
import { HAZARDS } from "../../scoring/types";
import type { AgentContext } from "../context";
import { hubLabel, round1, runTool, type ToolRuntime } from "./shared";

/**
 * Builds the explain_hub_score tool for one request.
 * @param ctx - agent context.
 * @param runtime - ledger and callbacks.
 * @param hubIdSchema - Zod enum of the active hub ids (G12).
 * @returns the AI SDK tool.
 */
export function buildExplainHubScoreTool(ctx: AgentContext, runtime: ToolRuntime, hubIdSchema: z.ZodEnum) {
  return tool({
    description:
      "Full breakdown of ONE hub's risk score: every hazard with its inputs, weights, the overall formula with its numbers, " +
      "level, rank and confidence reasons. Use for 'why is X risky?' and BEFORE agreeing with any claim about a hub's level.",
    inputSchema: z.object({ hubId: hubIdSchema }),
    execute: (input) =>
      runTool("explain_hub_score", input, runtime, () => {
        const snapshot = ctx.snapshotByHub.get(input.hubId);
        if (!snapshot) throw new Error(`No score available for hub "${input.hubId}".`);
        const hub = ctx.hubById.get(input.hubId)!;
        const all = [...ctx.snapshotByHub.values()];
        const rankOf = (score: (s: typeof snapshot) => number) =>
          competitionRanks(all.map((s) => ({ id: s.hubId, score: score(s) }))).get(input.hubId);
        const worst = snapshot.hazards[snapshot.topHazard].score;

        return {
          hubId: hub.id,
          hub: hubLabel(hub),
