export async function loadWidgetsData(): Promise<WidgetsData> {
  const [hubs, snapshots, weatherBounds] = await Promise.all([listActiveHubs(), getLatestSnapshots(), getWeatherBounds()]);
  if (!snapshots || snapshots.length === 0 || !weatherBounds) {
    throw new BoundaryError({
      name: "NoDataError",
      message: "No scores yet — run `npm run ingest` first",
      functionName: "loadWidgetsData",
      boundary: "database",
    });
  }
  return buildWidgetsData({ hubs, snapshots, weatherBounds });
}

/**
 * @module app/api/_lib/http
 *
 * Shared plumbing for API routes (the `_lib` folder is private — not a route):
 * auth checks (second layer behind proxy.ts, A2) and friendly JSON errors (A4).
 */
import { getAccessEnv } from "@/core/config/env";
import { describeUnknownError, formatBoundaryMessage } from "@/core/errors/boundaryError";
import { toUserError, userError, type UserError } from "@/core/errors/userErrors";
import { isCronAuthorized, isSiteAuthorized } from "@/core/security/auth";

/** Never cache API responses: they're per-user or change nightly. */
const NO_STORE = { "Cache-Control": "no-store" };

/**
 * JSON response with no caching.
 * @param body - response body.
 * @param status - HTTP status.
 * @returns the response.
 */
export function json(body: unknown, status = 200): Response {
  return Response.json(body, { status, headers: NO_STORE });
}

/**
 * Friendly error response `{ error: { code, message, hint, retryable } }`.
 * @param error - the user error.
 * @returns the response.
 */
export function errorResponse(error: UserError): Response {
  const { status, ...body } = error;
  const headers: Record<string, string> = { ...NO_STORE };
  if (status === 401) headers["WWW-Authenticate"] = 'Basic realm="The Daily Prophet", charset="UTF-8"';
  return Response.json({ error: body }, { status, headers });
}

/**
 * Logs an unexpected failure (technical detail stays server-side) and returns the friendly response.
 * @param error - what was thrown.
 * @param functionName - the route function, for the log line.
 * @returns the error response.
 */
export function failure(error: unknown, functionName: string): Response {
  console.error(
    formatBoundaryMessage({
      name: error instanceof Error ? error.name : "UnknownError",
      message: describeUnknownError(error),
      functionName,
      boundary: "apiRoute",
    }),
  );
  return errorResponse(toUserError(error));
}

/**
 * Second auth layer for site routes.
 * @param request - the incoming request.
 * @returns a 401 response when not signed in, otherwise null.
 */
export function requireSiteAuth(request: Request): Response | null {
  return isSiteAuthorized(request.headers.get("authorization"), getAccessEnv()) ? null : errorResponse(userError("unauthorized"));
}

/**
 * Auth for the cron route (Bearer CRON_SECRET).
 * @param request - the incoming request.
 * @returns a 401 response when the secret is wrong, otherwise null.
 */
export function requireCronAuth(request: Request): Response | null {
  return isCronAuthorized(request.headers.get("authorization"), getAccessEnv()) ? null : errorResponse(userError("unauthorized"));
}

/**
 * POST /api/chat — the agent's API (requirement 6). The UI calls this, never the LLM.
 * Body: { sessionId: uuid | null, message: string, units: "us" | "metric" }.
 * Streams the AI SDK chat protocol: session, progress, answer text, validated answer (A1).
 */
import { createUIMessageStreamResponse } from "ai";
import { answerQuestion } from "@/core/agent/answerQuestion";
import { createAnswerQuestionDeps } from "@/core/agent/createAnswerQuestionDeps";
import { buildChatStream, chatRequestSchema } from "@/core/api/chatStream";
import { failure, requireSiteAuth } from "../_lib/http";

/** Upper bound for one turn (the agent's own total timeout is 60 s; a validation retry may follow). */
export const maxDuration = 120;

/**
 * Answers one chat message as a stream.
 * @param request - the HTTP request.
 * @returns the streaming response, or a friendly JSON error before streaming starts.
 */
export async function POST(request: Request): Promise<Response> {
  try {
    const denied = requireSiteAuth(request);
    if (denied) return denied;
    const body = chatRequestSchema.parse(await request.json());
    const deps = createAnswerQuestionDeps();
    const stream = buildChatStream(body, (req, callbacks) => answerQuestion(req, deps, callbacks));
    return createUIMessageStreamResponse({ stream, headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return failure(error, "POST /api/chat");
  }
}

/**
 * GET /api/widgets — data for the dashboard widgets (A5): top hubs, hazard
 * leaders, data freshness. Deterministic, no LLM.
 */
import { loadWidgetsData } from "@/core/widgets/loadWidgetsData";
import { failure, json, requireSiteAuth } from "../_lib/http";

/**
 * Returns the widget data.
 * @param request - the HTTP request.
 * @returns JSON widget data or a friendly error.
 */
export async function GET(request: Request): Promise<Response> {
  try {
    const denied = requireSiteAuth(request);
    if (denied) return denied;
    return json(await loadWidgetsData());
  } catch (error) {
    return failure(error, "GET /api/widgets");
  }
}

/**
 * GET /api/cron/ingest — the nightly job (A3, D14, D54): fetch new weather
 * days (+ FEMA for new hubs), then re-score every hub under one run id.
 * Called by Vercel Cron with `Authorization: Bearer <CRON_SECRET>`; not behind
 * the site login (proxy.ts excludes /api/cron).
 */
import { createIngestDeps } from "@/core/ingest/createIngestDeps";
import { runIngestThenScore } from "@/core/pipeline/runIngestThenScore";
import { createScoringDeps } from "@/core/scoring/createScoringDeps";
import { failure, json, requireCronAuth } from "../../_lib/http";

/** Vercel Hobby allows up to 300 s; a nightly run takes about a minute. */
export const maxDuration = 300;

/**
 * Runs the pipeline and returns a short summary.
 * @param request - the HTTP request.
 * @returns JSON summary, or a friendly error.
 */
export async function GET(request: Request): Promise<Response> {
  try {
    const denied = requireCronAuth(request);
    if (denied) return denied;
    const log = (line: string) => console.log(`[cron] ${line}`);
    const { ingest, scoring } = await runIngestThenScore(
      { trigger: "cron" },
      { ingest: createIngestDeps(log), scoring: createScoringDeps(log) },
    );
    const ok = ingest.hubsFailed === 0 && scoring.hubsFailed === 0;
    return json(
      {
        ok,
        runId: ingest.runId,
        hubs: ingest.hubsProcessed,
        weatherRowsSaved: ingest.weatherRowsSaved,
        hubsScored: scoring.hubsScored,
        failedHubs: [...ingest.results, ...scoring.results].filter((r) => r.error).map((r) => r.hubId),
      },
      ok ? 200 : 207,
    );
  } catch (error) {
    return failure(error, "GET /api/cron/ingest");
  }
}

/**
 * First auth layer (Q16, A2): HTTP Basic Auth on every page and API route,
 * except /api/cron (it has its own secret) and static assets. API routes check
 * again themselves, because proxy alone is not a full authorization solution.
 */
import { NextResponse, type NextRequest } from "next/server";
import { getAccessEnv } from "@/core/config/env";
import { userError } from "@/core/errors/userErrors";
import { isSiteAuthorized } from "@/core/security/auth";

const CHALLENGE = { "WWW-Authenticate": 'Basic realm="The Daily Prophet", charset="UTF-8"' };

/**
 * Lets signed-in requests through; asks the browser for credentials otherwise.
 * @param request - the incoming request.
 * @returns the next response, or a 401 (JSON for APIs, friendly text for pages).
 */
export function proxy(request: NextRequest): NextResponse {
  let access;
  try {
    access = getAccessEnv();
  } catch {
    return new NextResponse("The Daily Prophet isn't configured yet (site login missing).", { status: 500 });
  }
  if (isSiteAuthorized(request.headers.get("authorization"), access)) return NextResponse.next();

  const { status, ...body } = userError("unauthorized");
  if (request.nextUrl.pathname.startsWith("/api/")) {
    return NextResponse.json({ error: body }, { status, headers: CHALLENGE });
  }
  return new NextResponse(`${body.message} ${body.hint}`, {
    status,
    headers: { ...CHALLENGE, "Content-Type": "text/plain; charset=utf-8" },
  });
}

export const config = {
  matcher: ["/((?!api/cron|_next/static|_next/image|favicon.ico).*)"],
};

