            ))}
            <tr>
              <th scope="row" className="text-left text-xs font-medium text-slate-200">
                Overall
              </th>
              {data.hubs.map((hub) => (
                <td key={hub.hubId} className="px-1 py-1">
                  <LevelChip level={hub.level} score={hub.overallScore} />
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>
    </figure>
  );
}

