/**
 * A small pill showing a risk level — color AND text, never color alone.
 */
import type { RiskLevel } from "@/core/scoring/types";
import { LEVEL_UI } from "../_lib/labels";

/** Props for {@link LevelChip}. */
interface LevelChipProps {
  level: RiskLevel;
  /** Optional score to show before the label, e.g. "72.4 · High". */
  score?: number;
}

/** Renders a level pill. */
export function LevelChip({ level, score }: LevelChipProps) {
  const ui = LEVEL_UI[level];
  return (
    <span
      className="inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-xs font-medium tabular-nums"
      style={{ color: ui.text, background: ui.bg, borderColor: ui.border }}
    >
      {score !== undefined && <span>{score}</span>}
      {score !== undefined && <span aria-hidden="true">·</span>}
      {ui.label}
    </span>
  );
}

/**
 * Score breakdown (U3b): WHERE a hub's score comes from, in one strip —
 * each hazard's points (0.6 × weight × score) plus the worst-hazard boost.
 * All numbers come from the explain_hub_score tool (computed in code).
 */
import type { ExplainHubScoreOutput } from "@/core/agent/tools/explainHubScore";
import { HAZARD_UI } from "../../_lib/labels";
import { LevelChip } from "../LevelChip";

/** Props for {@link ScoreBreakdown}. */
interface ScoreBreakdownProps {
  data: ExplainHubScoreOutput;
}

/** Renders the score breakdown strip and its legend. */
export function ScoreBreakdown({ data }: ScoreBreakdownProps) {
  const { contributions, worstHazardBoost, calculation } = data.formula;
  const total = contributions.reduce((sum, c) => sum + c.points, 0) + worstHazardBoost;
  const pct = (points: number) => `${total > 0 ? (points / total) * 100 : 0}%`;
  const scores = Object.fromEntries(data.hazards.map((h) => [h.hazard, h]));
  const worst = HAZARD_UI[data.topHazard];

  return (
    <figure className="space-y-3">
      <figcaption className="flex flex-wrap items-baseline justify-between gap-2">
        <span className="text-sm font-medium text-slate-200">Where {data.hub}&apos;s score comes from</span>
        <LevelChip level={data.level} score={data.overallScore} />
      </figcaption>

      <div className="flex h-4 w-full overflow-hidden rounded-full bg-white/5" role="img" aria-label={`Score breakdown: ${calculation}`}>
        {contributions
          .filter((c) => c.points > 0)
          .map((c) => (
            <div
              key={c.hazard}
              style={{ width: pct(c.points), background: HAZARD_UI[c.hazard].color }}
              title={`${HAZARD_UI[c.hazard].label}: +${c.points}`}
            />
          ))}
        <div
          style={{
            width: pct(worstHazardBoost),
            background: `repeating-linear-gradient(135deg, ${worst.color}, ${worst.color} 4px, transparent 4px, transparent 8px)`,
          }}
          title={`Worst-hazard boost (${worst.label}): +${worstHazardBoost}`}
        />
      </div>

      <ul className="grid grid-cols-1 gap-x-6 gap-y-1.5 text-xs sm:grid-cols-2">
        {contributions.map((c) => (
          <li key={c.hazard} className="flex items-center gap-2 text-slate-300">
            <span className="h-2.5 w-2.5 shrink-0 rounded-sm" style={{ background: HAZARD_UI[c.hazard].color }} aria-hidden="true" />
            <span className="flex-1">{HAZARD_UI[c.hazard].label}</span>
            <span className="tabular-nums text-slate-400">score {scores[c.hazard].score}</span>
            <span className="w-12 text-right tabular-nums text-slate-200">+{c.points}</span>
          </li>
        ))}
        <li className="flex items-center gap-2 text-slate-300">
          <span className="h-2.5 w-2.5 shrink-0 rounded-sm border border-white/40" aria-hidden="true" />
          <span className="flex-1">Worst-hazard boost ({worst.label})</span>
          <span className="w-12 text-right tabular-nums text-slate-200">+{worstHazardBoost}</span>
        </li>
      </ul>
      <p className="font-mono text-[11px] text-slate-500">Overall = {calculation}</p>
    </figure>
  );
}

/**
 * Comparison grid (U3b): hubs × hazards at a glance — each cell is a score
 * with its level color AND text. Numbers come from the compare_hubs tool.
 */
import type { CompareHubsOutput } from "@/core/agent/tools/compareHubs";
import type { Hazard } from "@/core/scoring/types";
import { HAZARD_UI, LEVEL_UI } from "../../_lib/labels";
import { LevelChip } from "../LevelChip";

/** Props for {@link ComparisonGrid}. */
interface ComparisonGridProps {
  data: CompareHubsOutput;
}

/** Renders the comparison table. */
export function ComparisonGrid({ data }: ComparisonGridProps) {
  const hazards = Object.keys(data.hubs[0]?.hazards ?? {}) as Hazard[];
  return (
    <figure className="space-y-2">
      <figcaption className="text-sm font-medium text-slate-200">Side by side</figcaption>
      <div className="overflow-x-auto">
        <table className="w-full border-separate border-spacing-1 text-sm">
          <thead>
            <tr>
              <th className="text-left text-xs font-normal text-slate-400" scope="col">
                Hazard
              </th>
              {data.hubs.map((hub) => (
                <th key={hub.hubId} className="text-left text-xs font-medium text-slate-200" scope="col">
                  {hub.hub}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {hazards.map((hazard) => (
              <tr key={hazard}>
                <th scope="row" className="whitespace-nowrap text-left text-xs font-normal text-slate-300">
                  <span aria-hidden="true">{HAZARD_UI[hazard].icon} </span>
                  {HAZARD_UI[hazard].label}
                </th>
                {data.hubs.map((hub) => {
                  const cell = hub.hazards[hazard];
                  const ui = LEVEL_UI[cell.level];
                  return (
                    <td
                      key={hub.hubId}
                      className="rounded-md border px-2 py-1 tabular-nums"
                      style={{ background: ui.bg, borderColor: ui.border }}
                      title={`${cell.confidenceReason} (rank ${cell.rankAmongAll} of ${data.totalHubs})`}
                    >
                      <span className="font-medium" style={{ color: ui.text }}>
                        {cell.score}
                      </span>{" "}
                      <span className="text-xs text-slate-400">{ui.label}</span>
                    </td>
                  );
                })}
              </tr>
            ))}
            <tr>
              <th scope="row" className="text-left text-xs font-medium text-slate-200">
                Overall
              </th>
              {data.hubs.map((hub) => (
                <td key={hub.hubId} className="px-1 py-1">
                  <LevelChip level={hub.level} score={hub.overallScore} />
                </td>
