            <dt>Last scored</dt>
            <dd className="text-slate-300">{relativeTime(data.dataStatus.scoredAt)}</dd>
          </div>
          <div className="flex justify-between gap-2">
            <dt>Hazard data</dt>
            <dd className="text-right text-slate-300">{data.dataStatus.femaVersion}</dd>
          </div>
        </dl>
      </Panel>
    </div>
  );
}

