"use client";
/**
 * Chat history (U5b): THIS browser's past chats, newest first. Opening one
 * restores its questions and validated answers; "New chat" starts fresh.
 */
import { useEffect, useState } from "react";
import type { SessionSummary } from "@/core/db/chatTranscript";
import { relativeTime } from "../_lib/labels";

/** Props for {@link SideNav}. */
interface SideNavProps {
  sessionIds: string[];
  activeId: string | null;
  onOpen: (id: string) => void;
  onNew: () => void;
}

/** Renders the chat list. */
export function SideNav({ sessionIds, activeId, onOpen, onNew }: SideNavProps) {
  const [sessions, setSessions] = useState<SessionSummary[]>([]);

  useEffect(() => {
    if (sessionIds.length === 0) return;
    let alive = true;
    fetch(`/api/chat/sessions?ids=${sessionIds.join(",")}`)
      .then((res) => (res.ok ? res.json() : { sessions: [] }))
      .then((json: { sessions: SessionSummary[] }) => alive && setSessions(json.sessions))
      .catch(() => alive && setSessions([]));
    return () => {
      alive = false;
    };
  }, [sessionIds]);

  return (
    <nav className="flex h-full flex-col gap-3" aria-label="Your chats">
      <button
        type="button"
        onClick={onNew}
        className="rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-sm text-slate-100 transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
      >
        + New chat
      </button>
      <h2 className="px-1 text-xs font-medium uppercase tracking-wide text-slate-500">Your chats</h2>
      {sessions.length === 0 ? (
        <p className="px-1 text-xs leading-relaxed text-slate-500">Your conversations will appear here. They&apos;re saved for this browser only.</p>
      ) : (
        <ul className="-mx-1 space-y-0.5 overflow-y-auto">
          {sessions.map((session) => (
            <li key={session.id}>
              <button
                type="button"
                onClick={() => onOpen(session.id)}
                aria-current={session.id === activeId ? "true" : undefined}
                className={`w-full rounded-lg px-2 py-1.5 text-left transition hover:bg-white/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60 ${
                  session.id === activeId ? "bg-white/[0.07]" : ""
                }`}
              >
                <span className="block truncate text-sm text-slate-200">{session.title ?? "Untitled chat"}</span>
                {session.lastMessageAt && <span className="text-[11px] text-slate-500">{relativeTime(session.lastMessageAt)}</span>}
              </button>
            </li>
          ))}
        </ul>
      )}
    </nav>
  );
}

/**
 * Masthead (U1): wordmark, data freshness, the US/Metric switch (D60), new chat.
 */
import type { UnitSystem } from "@/core/utils/units";

/** Props for {@link Header}. */
interface HeaderProps {
  units: UnitSystem;
  onUnitsChange: (units: UnitSystem) => void;
  /** e.g. "36 hubs · weather through 2026-11-24" (null while loading). */
  freshness: string | null;
  onNew: () => void;
  onToggleNav: () => void;
}

/** Renders the masthead. */
export function Header({ units, onUnitsChange, freshness, onNew, onToggleNav }: HeaderProps) {
  const segment = (value: UnitSystem, label: string) => (
    <button
      type="button"
      role="radio"
      aria-checked={units === value}
      onClick={() => onUnitsChange(value)}
      className={`rounded-md px-2.5 py-1 text-xs transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60 ${
        units === value ? "bg-white/15 text-slate-50" : "text-slate-400 hover:text-slate-200"
      }`}
    >
      {label}
    </button>
  );
  return (
    <header className="flex flex-wrap items-center gap-x-4 gap-y-2 border-b border-white/5 px-4 py-3 sm:px-6">
      <button
        type="button"
        onClick={onToggleNav}
        className="rounded-lg border border-white/10 px-2 py-1 text-sm text-slate-300 lg:hidden"
        aria-label="Show your chats"
      >
        ☰
      </button>
      <div className="min-w-0 flex-1">
        <h1 className="text-lg font-medium tracking-tight text-slate-50">
          <span aria-hidden="true">🦉 </span>The Daily Prophet
        </h1>
        <p className="truncate text-xs text-slate-400">Weather risk intelligence for our hubs{freshness ? ` · ${freshness}` : ""}</p>
      </div>
      <div role="radiogroup" aria-label="Units" className="flex rounded-lg border border-white/10 bg-white/5 p-0.5">
        {segment("us", "US")}
        {segment("metric", "Metric")}
      </div>
      <button
        type="button"
        onClick={onNew}
        className="hidden rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 text-xs text-slate-200 transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60 sm:block"
      >
        + New chat
      </button>
    </header>
  );
}

/**
 * First screen (U4 empty state): a one-line intro and the brief's example questions.
 */
import { EXAMPLE_QUESTIONS } from "../_lib/labels";

/** Props for {@link EmptyState}. */
interface EmptyStateProps {
  onAsk: (question: string) => void;
}

/** Renders the welcome and example questions. */
export function EmptyState({ onAsk }: EmptyStateProps) {
  return (
    <div className="mx-auto max-w-xl space-y-6 py-10 text-center">
      <div className="space-y-2">
        <p className="text-4xl" aria-hidden="true">
          🐱
        </p>
        <h2 className="text-xl font-medium text-slate-100">Which hubs should we protect first?</h2>
        <p className="text-sm text-slate-400">
          Ask about weather risk at our 36 hubs — rankings, comparisons, history, or why a hub scores the way it does. Every number comes
          from the data, and I&apos;ll tell you when the data is unsure.
        </p>
      </div>
      <ul className="grid gap-2 text-left sm:grid-cols-2">
        {EXAMPLE_QUESTIONS.map((question) => (
          <li key={question}>
            <button
              type="button"
              onClick={() => onAsk(question)}
              className="glass h-full w-full rounded-xl px-4 py-3 text-sm text-slate-200 transition hover:border-sky-300/30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
            >
              {question}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

"use client";
/**
 * The message box (U7): Enter sends, Shift+Enter adds a line, Stop while answering.
 */
import { useState, type FormEvent, type KeyboardEvent } from "react";

/** Longest message the API accepts (mirrors AGENT_LIMITS.maxUserMessageChars). */
const MAX_CHARS = 1_000;

/** Props for {@link Composer}. */
interface ComposerProps {
  busy: boolean;
  onSend: (text: string) => void;
  onStop: () => void;
}

/** Renders the composer. */
export function Composer({ busy, onSend, onStop }: ComposerProps) {
  const [text, setText] = useState("");
  const tooLong = text.length > MAX_CHARS;

  const submit = (event?: FormEvent) => {
    event?.preventDefault();
    const trimmed = text.trim();
    if (!trimmed || busy || tooLong) return;
    onSend(trimmed);
    setText("");
  };
  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
      event.preventDefault();
      submit();
    }
  };

  return (
    <form onSubmit={submit} className="glass flex items-end gap-2 rounded-2xl p-2">
      <label htmlFor="question" className="sr-only">
        Your question
      </label>
      <textarea
        id="question"
        rows={1}
        value={text}
        onChange={(event) => setText(event.target.value)}
        onKeyDown={onKeyDown}
        placeholder="Ask about a hub, a hazard or a region…"
        className="max-h-40 min-h-10 flex-1 resize-none bg-transparent px-3 py-2 text-[15px] text-slate-100 placeholder:text-slate-500 focus:outline-none"
        aria-describedby={tooLong ? "too-long" : undefined}
      />
      {tooLong && (
        <span id="too-long" className="self-center text-xs text-amber-300">
          {text.length}/{MAX_CHARS}
        </span>
      )}
      {busy ? (
        <button
          type="button"
          onClick={onStop}
          className="rounded-xl border border-white/15 px-4 py-2 text-sm text-slate-200 transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
        >
          Stop
        </button>
      ) : (
        <button
          type="submit"
          disabled={!text.trim() || tooLong}
          className="rounded-xl bg-sky-400/90 px-4 py-2 text-sm font-medium text-slate-950 transition hover:bg-sky-300 disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-200"
        >
          Ask
        </button>
      )}
    </form>
  );
}

