// Drives the real app in headless Chrome via the DevTools protocol (no dependencies; Node 22 WebSocket).
// Usage: node drive.cjs <repoDir> <outDir> <width> <height> [question ...]
// Signs in on EVERY request (like a browser after login). Credentials are read from .env.local, never printed.
const fs = require("fs"), path = require("path"), os = require("os"), { spawn } = require("child_process");
const [repo, outDir, width, height, ...questions] = process.argv.slice(2);
const env = Object.fromEntries(fs.readFileSync(path.join(repo, ".env.local"), "utf8").split(/\r?\n/)
  .filter((l) => /^[A-Z_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1).trim().replace(/^["']|["']$/g, "")]));
const auth = "Basic " + Buffer.from(`${env.APP_USERNAME}:${env.APP_PASSWORD}`).toString("base64");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const profile = fs.mkdtempSync(path.join(os.tmpdir(), "prophet-chrome-"));
  const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe",
    ["--headless=new", "--disable-gpu", "--hide-scrollbars", "--remote-debugging-port=9333", `--user-data-dir=${profile}`, "about:blank"], { stdio: "ignore" });
  let targets = [];
  for (let i = 0; i < 40 && !targets.length; i++) {
    await sleep(250);
    try { targets = (await (await fetch("http://127.0.0.1:9333/json/list")).json()).filter((t) => t.type === "page"); } catch {}
  }
  const ws = new WebSocket(targets[0].webSocketDebuggerUrl);
  await new Promise((r) => (ws.onopen = r));
  let id = 0; const pending = new Map();
  ws.onmessage = (m) => { const msg = JSON.parse(m.data); if (pending.has(msg.id)) { pending.get(msg.id)(msg.result ?? msg); pending.delete(msg.id); } };
  const send = (method, params = {}) => new Promise((r) => { pending.set(++id, r); ws.send(JSON.stringify({ id, method, params })); });
  const evaluate = async (expr) => (await send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true })).result?.value;
  const shot = async (name) => {
    const { contentSize } = await send("Page.getLayoutMetrics");
    const h = Math.min(Math.ceil(contentSize.height), 6000);
    const { data } = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: true, clip: { x: 0, y: 0, width: Number(width), height: h, scale: 1 } });
    fs.writeFileSync(path.join(outDir, name), Buffer.from(data, "base64"));
    console.log("saved", name, `(${width}x${h})`);
  };

  await send("Network.enable");
  await send("Network.setExtraHTTPHeaders", { headers: { Authorization: auth } });
  await send("Emulation.setDeviceMetricsOverride", { width: Number(width), height: Number(height), deviceScaleFactor: 1, mobile: Number(width) < 700 });
  await send("Page.enable");
  await send("Page.navigate", { url: "http://localhost:3100/" });
  await sleep(5000);
  await shot(`${width}-0-start.png`);

  for (const [i, q] of questions.entries()) {
    const t0 = Date.now();
    await evaluate(`(() => { const ta = document.querySelector('#question'); const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
      set.call(ta, ${JSON.stringify(q)}); ta.dispatchEvent(new Event('input', { bubbles: true })); return true; })()`);
    await sleep(300);
    await evaluate(`document.querySelector('form button[type=submit]').click()`);
    let done = false;
    for (let s = 0; s < 75 && !done; s++) {
      await sleep(2000);
      done = await evaluate(`(() => { const cards = [...document.querySelectorAll('article')]; const last = cards.at(-1);
        return !!last && (last.innerText.includes('How I got this') || !!last.querySelector('[role=alert]')) && !document.querySelector('[aria-busy=true] [aria-live]'); })()`);
    }
    console.log(`q${i + 1}: ${done ? "answered" : "TIMEOUT"} in ${((Date.now() - t0) / 1000).toFixed(1)}s`);
    await sleep(800);
    await shot(`${width}-${i + 1}.png`);
  }
  ws.close(); chrome.kill();
})().catch((e) => { console.error("drive failed:", e.message); process.exit(1); });

