    const t0 = Date.now();
    await evaluate(`(() => { const ta = document.querySelector('#question'); const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
      set.call(ta, ${JSON.stringify(q)}); ta.dispatchEvent(new Event('input', { bubbles: true })); return true; })()`);
