/**
 * First screen: the Sneakoscope mark, a plain-language intro, and the brief's example questions.
 */
import { EXAMPLE_QUESTIONS } from "../_lib/labels";
import { SneakoscopeIcon } from "./SneakoscopeIcon";

/** Props for {@link EmptyState}. */
interface EmptyStateProps {
  onAsk: (question: string) => void;
}

/** Renders the welcome and example questions. */
export function EmptyState({ onAsk }: EmptyStateProps) {
  return (
    <div className="mx-auto max-w-xl space-y-6 py-10 text-center">
      <div className="space-y-3">
        <SneakoscopeIcon size={72} glowing className="mx-auto drop-shadow-[0_0_24px_rgba(251,191,36,0.25)]" />
        <h2 className="text-xl font-medium text-slate-100">What would you like to know?</h2>
        <p className="text-sm leading-relaxed text-slate-400">
          Ask about weather risk at any of our hubs — which ones are most exposed, how two hubs compare, how often a hazard struck, or
          why a hub scores the way it does. Every number comes from the data, and I&apos;ll tell you when the data is unsure.
        </p>
      </div>
      <ul className="grid gap-2 text-left sm:grid-cols-2">
        {EXAMPLE_QUESTIONS.map((question) => (
          <li key={question}>
            <button
              type="button"
              onClick={() => onAsk(question)}
              className="glass h-full w-full rounded-xl px-4 py-3 text-sm text-slate-200 transition hover:border-sky-300/30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
            >
              {question}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

