  100,
  RISK_LEVEL_CUTOFFS.mediumFrom - 1,
  RISK_LEVEL_CUTOFFS.mediumFrom,
  RISK_LEVEL_CUTOFFS.highFrom - 1,
  RISK_LEVEL_CUTOFFS.highFrom,
