      label: "swallowed a false premise (Seattle hurricanes)",
      question: "Why is Seattle's hurricane risk so high?",
      answer: plantedAnswer(
        "Seattle's hurricane risk is high because Pacific storms regularly bring hurricane-force conditions to the hub.",
        "explain_hub_score",
        { hubId: "seattle" },
        seattle,
        { hubId: "seattle", hazard: "hurricane", claimedLevel: "high", actualLevel: "low", holds: false },
      ),
    },
  ];
  const details: string[] = [];
  let caught = 0;
  for (const p of planted) {
    try {
      const verdict = await judgeAnswer(p.question, p.answer, judge);
      const failed = !judgePasses(verdict);
      if (failed) caught++;
      details.push(`${failed ? "caught" : "MISSED"}: ${p.label} (verdict ${verdict.verdict}, faithful ${verdict.faithfulToData}/5)`);
    } catch (error) {
      details.push(`ERROR: ${p.label} — ${describeUnknownError(error)}`);
    }
  }
  return { caught, total: planted.length, details };
}

/**
 * @module evals/lib/judging
 *
 * Runs the independent judge over eval answers (J1–J3) and tests the judge
 * itself with planted bad answers (J4): a judge that passes a wrong number or a
 * swallowed false premise can't be trusted, and the report says so.
 */
import type { FinalAnswer } from "../../src/core/agent/answerSchema";
import type { AgentContext } from "../../src/core/agent/context";
import { explainHubScoreOutput } from "../../src/core/agent/tools/explainHubScore";
import { describeUnknownError } from "../../src/core/errors/boundaryError";
import { judgeAnswer, judgePasses, type JudgeModel, type JudgeVerdict } from "../../src/core/judge/judgeAnswer";
import { check } from "./checks";
import type { CheckResult, TurnResult } from "./types";

/** The judge's verdict for one turn (or why there is none). */
export interface TurnJudgment {
  question: string;
  verdict: JudgeVerdict | null;
  error?: string;
}

/**
 * Judges every answered turn of a case run. The judge sees what the agent saw:
 * its system prompt and, in follow-ups, earlier turns' tool results (D65).
 * @param results - the case's turns.
 * @param judge - the judge model.
 * @param ctx - agent context (to rebuild the agent's system prompt).
 * @returns judgments and the matching hard checks (J3: pass AND faithful ≥ 4).
 */
export async function judgeTurns(
  results: TurnResult[],
  judge: JudgeModel,
  ctx: AgentContext,
): Promise<{ judgments: TurnJudgment[]; checks: CheckResult[] }> {
  const briefing = buildSystemPrompt(ctx);
  const judgments: TurnJudgment[] = [];
  const checks: CheckResult[] = [];
  for (const [i, turn] of results.entries()) {
    if (!turn.answer) continue;
    const earlierToolCalls = results.slice(0, i).flatMap((r) => r.answer?.meta.toolCalls ?? []);
    try {
      const verdict = await judgeAnswer(turn.question, turn.answer, judge, { briefing, earlierToolCalls });
      judgments.push({ question: turn.question, verdict });
      const unsupported = verdict.unsupportedClaims.length ? ` · unsupported: ${verdict.unsupportedClaims.join("; ")}` : "";
      checks.push(
        check(
          `judge: turn ${i + 1} faithful & correct`,
          judgePasses(verdict),
          `verdict ${verdict.verdict}, faithful ${verdict.faithfulToData}/5 — ${verdict.reason}${unsupported}`,
        ),
      );
    } catch (error) {
      judgments.push({ question: turn.question, verdict: null, error: describeUnknownError(error) });
      checks.push(check(`judge: turn ${i + 1} faithful & correct`, false, `judge unavailable: ${describeUnknownError(error)}`));
    }
  }
  return { judgments, checks };
}

/** Result of the judge self-test (J4). */
export interface JudgeSelfTest {
  caught: number;
  total: number;
  details: string[];
}

/** A minimal answer built around one real tool result. */
function plantedAnswer(text: string, tool: string, input: object, output: unknown, premiseCheck: FinalAnswer["premiseCheck"]): FinalAnswer {
  return {
    answer: text,
    outOfScope: false,
    hubsMentioned: [],
    dataUsed: [],
    premiseCheck,
    confidence: "high",
    assumptions: [],
    limitations: [],
    followUpSuggestions: [],
    recommendation: null,
    meta: { model: "planted", toolCalls: [{ tool, input, output }], warnings: [], retried: false, confidenceOverridden: false },
  };
}

/**
 * Plants two clearly bad answers built on REAL tool results and checks the judge fails both (J4).
 * @param ctx - agent context (real data).
 * @param judge - the judge model.
 * @returns how many bad answers the judge caught.
 */
export async function judgeSelfTest(ctx: AgentContext, judge: JudgeModel): Promise<JudgeSelfTest> {
  const dallas = explainHubScoreOutput(ctx, { hubId: "dallas" });
  const seattle = explainHubScoreOutput(ctx, { hubId: "seattle" });
  const wrongScore = Math.round((dallas.overallScore + 15.3) * 10) / 10;
  const planted = [
    {
      label: "wrong number + wrong driver (Dallas)",
      question: "Why is the Dallas hub's weather disruption risk high?",
      answer: plantedAnswer(
        `Dallas scores ${wrongScore} overall, ranking 1st of 36 hubs, driven mostly by hurricanes.`,
        "explain_hub_score",
        { hubId: "dallas" },
        dallas,
        { hubId: "dallas", hazard: null, claimedLevel: "high", actualLevel: dallas.level, holds: dallas.level === "high" },
      ),
    },
    {
      label: "swallowed a false premise (Seattle hurricanes)",
      question: "Why is Seattle's hurricane risk so high?",
      answer: plantedAnswer(
        "Seattle's hurricane risk is high because Pacific storms regularly bring hurricane-force conditions to the hub.",
        "explain_hub_score",
        { hubId: "seattle" },
        seattle,
        { hubId: "seattle", hazard: "hurricane", claimedLevel: "high", actualLevel: "low", holds: false },
      ),
    },
  ];
  const details: string[] = [];
  let caught = 0;
  for (const p of planted) {
    try {
      const verdict = await judgeAnswer(p.question, p.answer, judge, { briefing: buildSystemPrompt(ctx), earlierToolCalls: [] });
      const failed = !judgePasses(verdict);
      if (failed) caught++;
      details.push(`${failed ? "caught" : "MISSED"}: ${p.label} (verdict ${verdict.verdict}, faithful ${verdict.faithfulToData}/5)`);
    } catch (error) {
      details.push(`ERROR: ${p.label} — ${describeUnknownError(error)}`);
    }
  }
  return { caught, total: planted.length, details };
}

/**
 * @module scripts/eval
 *
 * `npm run eval` — runs the eval set (E1–E7) and prints pass/fail per case + totals.
 *
 *   npm run eval                              in-process, model from OPENROUTER_MODEL
 *   npm run eval -- --model=[removed]   try another OpenRouter model (Step 8 bakeoff)
 *   npm run eval -- --repeat=3                run each case 3 times (consistency)
 *   npm run eval -- --case=denver-snow,top-5  only some cases
 *   npm run eval -- --url=https://…           against a deployed /api/chat
 *   npm run eval -- --publish                 also write docs/evals.md
 *   npm run eval -- --no-judge                skip the independent judge (J1–J4)
 *
 * Exit code 1 when any case fails. A JSON + Markdown report is saved in evals/results/.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { getAccessEnv } from "../src/core/config/env";
import { createAnswerQuestionDeps } from "../src/core/agent/createAnswerQuestionDeps";
import { recordEvent } from "../src/core/db/eventsRepository";
import { createJudgeModel } from "../src/core/judge/judgeAnswer";
import { EVAL_CASES } from "../evals/cases";
import { judgeSelfTest, judgeTurns } from "../evals/lib/judging";
import { buildOracle } from "../evals/lib/oracle";
import { fetchPricing, markdownSummary, printFloodReview, printJudgeReport, printReport, softMetrics } from "../evals/lib/report";
import { runInProcess, runRemote } from "../evals/lib/runners";
import type { CaseRun } from "../evals/lib/types";

/** Reads `--name=value` (or PowerShell's `npm_config_name`). */
function flag(name: string): string | undefined {
  const arg = process.argv.find((a) => a.startsWith(`--${name}=`));
  return arg ? arg.slice(name.length + 3) : process.env[`npm_config_${name}`];
}

/** Reads a boolean `--name` flag. */
const has = (name: string) => process.argv.includes(`--${name}`) || process.env[`npm_config_${name}`] === "true";

/** Runs the evals. */
async function main(): Promise<void> {
  const url = flag("url");
  const repeat = Math.max(1, Number(flag("repeat") ?? 1));
  const only = flag("case")?.split(",").map((s) => s.trim());
  const cases = only ? EVAL_CASES.filter((c) => only.includes(c.id)) : EVAL_CASES;
  if (cases.length === 0) throw new Error(`No cases match --case=${only?.join(",")}. Known: ${EVAL_CASES.map((c) => c.id).join(", ")}`);

  // The oracle always reads the same data the agent sees (local DB access needed even in --url mode).
  const deps = createAnswerQuestionDeps({ modelOverride: flag("model") });
  const context = await deps.loadContext({ today: deps.today(), units: "us" });
  const oracle = buildOracle(context);
  const access = url ? getAccessEnv() : null;
  const label = url ? `remote ${url}` : deps.agentModel.modelId;

  const judge = has("no-judge") ? null : createJudgeModel();
  console.log(`Running ${cases.length} case(s) × ${repeat} on ${label}${judge ? `, judged by ${judge.modelId}` : ""}…`);
  const selfTest = judge ? await judgeSelfTest(context, judge) : null;
  const runs: CaseRun[] = [];
  for (let round = 1; round <= repeat; round++) {
    for (const evalCase of cases) {
      const results = url
        ? await runRemote(evalCase, {
            baseUrl: url,
            authorization: `Basic ${Buffer.from(`${access!.APP_USERNAME}:${access!.APP_PASSWORD}`).toString("base64")}`,
          })
        : await runInProcess(evalCase, deps.agentModel, context);
      const checks = await evalCase.check(results, oracle);
      const judged = judge ? await judgeTurns(results, judge) : null;
      const allChecks = [...checks, ...(judged?.checks ?? [])];
      const run = { caseId: evalCase.id, title: evalCase.title, results, checks: allChecks, pass: allChecks.every((c) => c.pass), judgments: judged?.judgments };
      runs.push(run);
      process.stdout.write(`${run.pass ? "." : "F"}`);
    }
  }

  const pricing = url ? null : await fetchPricing(deps.agentModel.modelId);
  const metrics = softMetrics(runs, pricing);
  printReport(runs, metrics, `${label}${repeat > 1 ? ` · ${repeat} runs/case` : ""}`);
  printJudgeReport(runs, selfTest, judge?.modelId ?? null);
  printFloodReview(context);

  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const outDir = join("evals", "results");
  mkdirSync(outDir, { recursive: true });
  const fileBase = join(outDir, `${stamp}-${label.replace(/[^a-z0-9.-]+/gi, "_")}`);
  const markdown = markdownSummary(runs, metrics, {
    label,
    date: new Date().toISOString().slice(0, 16).replace("T", " ") + " UTC",
    repeat,
    judgeModel: judge?.modelId ?? null,
    selfTest,
  });
  writeFileSync(`${fileBase}.json`, JSON.stringify({ label, repeat, metrics, judge: judge?.modelId ?? null, selfTest, runs }, null, 2));
  writeFileSync(`${fileBase}.md`, markdown);
  if (has("publish")) writeFileSync(join("docs", "evals.md"), markdown);
  console.log(`\nReport: ${fileBase}.md${has("publish") ? " (+ docs/evals.md)" : ""}`);

  const failed = runs.filter((r) => !r.pass);
  await recordEvent({
    eventType: "eval.finished",
    source: "eval",
    level: failed.length ? "warn" : "info",
    message: `${runs.length - failed.length}/${runs.length} runs passed on ${label}`,
    payload: {
      label,
      repeat,
      failedCases: [...new Set(failed.map((r) => r.caseId))],
      avgToolCalls: metrics.avgToolCalls,
      costUsd: metrics.costUsd,
      judge: judge?.modelId ?? null,
      judgeSelfTest: selfTest ? `${selfTest.caught}/${selfTest.total}` : null,
    },
  });
  if (failed.length) process.exit(1);
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});

