/**
 * @module scripts/bakeoff
 *
 * `npm run bakeoff -- <results.json> [more.json …]` — compares models from saved eval
 * results (no API calls) and writes docs/bakeoff.md (B6).
 *
 * Several files for the same model are pooled (e.g. a screen run + a --repeat=2 run).
 * Files graded by a judge other than JUDGE_MODEL (made with --rejudge and another
 * JUDGE_MODEL) go into the cross-judge table (B3) instead of the ranking.
 *
 * Winner rule (B4): 1) gate: zero failures on premise/data checks and p95 ≤ 30 s;
 * 2) accuracy: pass rate, where within 2 case-runs of the best counts as a tie;
 * 3) cheapest per answer among the tied; 4) fastest as the final tiebreak.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { getJudgeEnv } from "../src/core/config/env";
import { judgeAverages, softMetrics } from "../evals/lib/report";
import type { CaseRun } from "../evals/lib/types";

/** Hard UX limit on p95 seconds per answer (B4). */
const P95_LIMIT_SECONDS = 30;

/** Case-runs within this many of the best pass count are a tie (B4: noise). */
const TIE_BAND_RUNS = 2;

/** Check names that guard the "never wrong" promises: the premise verdict and the data (B4 gate). */
const GATE_CHECK = /premise|matches|computed|numbers|percentage/i;

/** A saved eval results file (scripts/eval.ts output). */
interface ResultsFile {
  label: string;
  judge: string | null;
  metrics: { turns: number; costUsd: number | null };
  runs: CaseRun[];
}

/** One model's pooled results. */
interface ModelSummary {
  model: string;
  caseRuns: number;
  passed: number;
  gateFailures: string[];
  codeFailures: number;
  judgeFailures: number;
  answers: number;
  costPerAnswer: number | null;
  avgSeconds: number;
  p95Seconds: number;
  avgToolCalls: number;
  duplicateCalls: number;
  untraced: number;
  retries: number;
  faithful: number | null;
  failedCases: string[];
}

/**
 * Pools one model's files into a summary.
 * @param model - model id.
 * @param files - that model's results files.
 * @returns the summary.
 */
function summarize(model: string, files: ResultsFile[]): ModelSummary {
  const runs = files.flatMap((f) => f.runs);
  const metrics = softMetrics(runs, null);
  const costs = files.map((f) => f.metrics.costUsd);
  const totalCost = costs.every((c) => c !== null) ? costs.reduce((s, c) => s + c!, 0) : null;
  const failed = runs.flatMap((r) => r.checks.filter((c) => !c.pass).map((c) => ({ caseId: r.caseId, name: c.name })));
  return {
    model,
    caseRuns: runs.length,
    passed: runs.filter((r) => r.pass).length,
    gateFailures: failed.filter((c) => !c.name.startsWith("judge:") && GATE_CHECK.test(c.name)).map((c) => `${c.caseId}: ${c.name}`),
    codeFailures: failed.filter((c) => !c.name.startsWith("judge:")).length,
    judgeFailures: failed.filter((c) => c.name.startsWith("judge:")).length,
    answers: metrics.turns,
    costPerAnswer: totalCost !== null && metrics.turns ? totalCost / metrics.turns : null,
    avgSeconds: metrics.avgSeconds,
    p95Seconds: metrics.p95Seconds,
    avgToolCalls: metrics.avgToolCalls,
    duplicateCalls: metrics.duplicateCalls,
    untraced: metrics.untracedNumbers,
    retries: metrics.retries,
    faithful: judgeAverages(runs)?.faithfulToData ?? null,
    failedCases: [...new Set(runs.filter((r) => !r.pass).map((r) => r.caseId))],
  };
}

/**
 * Orders models by the B4 rule and says why each one lands where it does.
 * @param models - model summaries.
 * @returns ranked summaries with a short verdict each.
 */
export function rankModels(models: ModelSummary[]): { summary: ModelSummary; verdict: string }[] {
  const rate = (m: ModelSummary) => m.passed / Math.max(1, m.caseRuns);
  const gated = (m: ModelSummary) => m.gateFailures.length === 0 && m.p95Seconds <= P95_LIMIT_SECONDS;
  const eligible = models.filter(gated);
  const best = Math.max(0, ...eligible.map(rate));
  const tied = (m: ModelSummary) => gated(m) && rate(m) >= best - TIE_BAND_RUNS / Math.max(1, m.caseRuns);
  const order = (a: ModelSummary, b: ModelSummary) =>
    Number(tied(b)) - Number(tied(a)) ||
    Number(gated(b)) - Number(gated(a)) ||
    (tied(a) && tied(b) ? (a.costPerAnswer ?? Infinity) - (b.costPerAnswer ?? Infinity) || a.avgSeconds - b.avgSeconds : rate(b) - rate(a));
  return [...models].sort(order).map((summary, i) => ({
    summary,
    verdict: !gated(summary)
      ? summary.gateFailures.length
        ? "❌ fails the data/premise gate"
        : `❌ p95 over ${P95_LIMIT_SECONDS}s`
      : tied(summary)
        ? i === 0
          ? "🏆 top accuracy, cheapest"
          : "tied on accuracy, costs more"
        : "less accurate",
  }));
}

/** Formats a number to fixed decimals. */
const f = (n: number, d = 1) => n.toFixed(d);

/** Formats a USD amount per answer. */
const usd = (n: number | null) => (n === null ? "n/a" : n < 0.01 ? `$${n.toFixed(4)}` : `$${n.toFixed(3)}`);

/** Runs the comparison. */
function main(): void {
  const paths = process.argv.slice(2).filter((a) => !a.startsWith("--"));
  if (paths.length === 0) throw new Error("Usage: npm run bakeoff -- <evals/results/…json> [more.json …]");
  const primaryJudge = getJudgeEnv().JUDGE_MODEL;
  const files = paths.map((p) => JSON.parse(readFileSync(p, "utf8")) as ResultsFile);
  const modelOf = (f: ResultsFile) => f.label.replace(/ \(rejudged\)$/, "");
  const primary = files.filter((f) => f.judge === primaryJudge);
  const cross = files.filter((f) => f.judge && f.judge !== primaryJudge);

  const byModel = new Map<string, ResultsFile[]>();
  for (const file of primary) byModel.set(modelOf(file), [...(byModel.get(modelOf(file)) ?? []), file]);
  const ranked = rankModels([...byModel].map(([model, fs]) => summarize(model, fs)));

  const rows = ranked.map(
    ({ summary: m, verdict }) =>
      `| ${m.model} | ${m.passed}/${m.caseRuns} | ${m.gateFailures.length} | ${m.judgeFailures} | ${usd(m.costPerAnswer)} | ` +
      `${f(m.avgSeconds)} / ${f(m.p95Seconds)} | ${f(m.avgToolCalls)} | ${m.duplicateCalls} | ${m.untraced} | ${m.retries} | ` +
      `${m.faithful === null ? "n/a" : f(m.faithful)} | ${verdict} |`,
  );
  const failures = ranked
    .filter(({ summary: m }) => m.failedCases.length)
    .map(({ summary: m }) => `- **${m.model}**: ${m.failedCases.join(", ")}${m.gateFailures.length ? ` · gate: ${m.gateFailures.join("; ")}` : ""}`);
  const crossRows = cross.map((file) => {
    const s = summarize(modelOf(file), [file]);
    const mainScore = byModel.get(modelOf(file)) ? summarize(modelOf(file), byModel.get(modelOf(file))!).faithful : null;
    return `| ${s.model} | ${file.judge} | ${s.faithful === null ? "n/a" : f(s.faithful)} | ${mainScore === null ? "n/a" : f(mainScore)} | ${s.judgeFailures} |`;
  });

  const markdown = `# Model bakeoff

Generated by \`npm run bakeoff\` from saved eval runs (same prompt, same 13 cases, no per-model tuning).
Rule (D107): **gate** (zero premise/data check failures, p95 ≤ ${P95_LIMIT_SECONDS}s) → **accuracy** (within ${TIE_BAND_RUNS} case-runs of the best = tie) → **cost per answer** → **speed**.

| Model | Cases passed | Gate fails | Judge fails | Cost / answer | Avg / p95 s | Tool calls | Dups | Untraced | Retries | Faithful (1–5) | Verdict |
|---|---|---|---|---|---|---|---|---|---|---|---|
${rows.join("\n")}

${failures.length ? `## Failed cases\n${failures.join("\n")}\n` : ""}
${
  crossRows.length
    ? `## Cross-judge check (B3)
The same answers re-graded by a judge from another provider, to catch a judge favoring its own model family.

| Model | Cross judge | Faithful (cross) | Faithful (${primaryJudge}) | Judge fails (cross) |
|---|---|---|---|---|
${crossRows.join("\n")}
`
    : ""
}`;
  console.log(markdown);
  if (process.argv.includes("--publish")) {
    writeFileSync("docs/bakeoff.md", markdown);
    console.log("Written to docs/bakeoff.md");
  }
}

try {
  main();
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
}

