  const byModel = new Map<string, ResultsFile[]>();
  for (const file of primary) byModel.set(modelOf(file), [...(byModel.get(modelOf(file)) ?? []), file]);
  const ranked = rankModels([...byModel].map(([model, fs]) => summarize(model, fs)));

  const rows = ranked.map(
    ({ summary: m, verdict }) =>
      `| ${m.model} | ${m.passed}/${m.caseRuns} | ${m.gateFailures.length} | ${m.judgeFailures} | ${usd(m.costPerAnswer)} | ` +
      `${f(m.avgSeconds)} / ${f(m.p95Seconds)} | ${f(m.avgToolCalls)} | ${m.duplicateCalls} | ${m.untraced} | ${m.retries} | ` +
      `${m.faithful === null ? "n/a" : f(m.faithful)} | ${verdict} |`,
  );
  const failures = ranked
    .filter(({ summary: m }) => m.failedCases.length)
    .map(({ summary: m }) => `- **${m.model}**: ${m.failedCases.join(", ")}${m.gateFailures.length ? ` · gate: ${m.gateFailures.join("; ")}` : ""}`);
  const crossRows = cross.map((file) => {
    const s = summarize(modelOf(file), [file]);
    const mainScore = byModel.get(modelOf(file)) ? summarize(modelOf(file), byModel.get(modelOf(file))!).faithful : null;
    return `| ${s.model} | ${file.judge} | ${s.faithful === null ? "n/a" : f(s.faithful)} | ${mainScore === null ? "n/a" : f(mainScore)} | ${s.judgeFailures} |`;
  });

  const markdown = `# Model bakeoff

Generated by \`npm run bakeoff\` from saved eval runs (same prompt, same 13 cases, no per-model tuning).
Rule (D107): **gate** (zero premise/data check failures, p95 ≤ ${P95_LIMIT_SECONDS}s) → **accuracy** (within ${TIE_BAND_RUNS} case-runs of the best = tie) → **cost per answer** → **speed**.

| Model | Cases passed | Gate fails | Judge fails | Cost / answer | Avg / p95 s | Tool calls | Dups | Untraced | Retries | Faithful (1–5) | Verdict |
|---|---|---|---|---|---|---|---|---|---|---|---|
${rows.join("\n")}

${failures.length ? `## Failed cases\n${failures.join("\n")}\n` : ""}
${
  crossRows.length
    ? `## Cross-judge check (B3)
The same answers re-graded by a judge from another provider, to catch a judge favoring its own model family.

| Model | Cross judge | Faithful (cross) | Faithful (${primaryJudge}) | Judge fails (cross) |
|---|---|---|---|---|
${crossRows.join("\n")}
`
    : ""
}`;
