import { MockLanguageModelV4 } from "ai/test";
import { describe, expect, it, vi } from "vitest";
import { ctx } from "./testFixtures";
import { runAgent } from "./runAgent";

// Shrink the step timeout so the test runs in well under a second.
vi.mock("./config", async (importOriginal) => {
  const original = await importOriginal<typeof import("./config")>();
  return { ...original, AGENT_LIMITS: { ...original.AGENT_LIMITS, timeouts: { totalMs: 2_000, stepMs: 200, toolMs: 1_000 } } };
});


/** A model that never answers: it waits until the SDK aborts the step. */
function hangingModel() {
  return new MockLanguageModelV4({
    doStream: async ({ abortSignal }) =>
      new Promise((_, reject) => {
        abortSignal?.addEventListener("abort", () => reject(abortSignal.reason));
      }),
  });
}

describe("runAgent step timeout (bakeoff crash)", () => {
  it("turns a slow model step into a clean LlmCallError, with no unhandled rejection", async () => {
    const unhandled: unknown[] = [];
    const onUnhandled = (reason: unknown) => unhandled.push(reason);
    process.on("unhandledRejection", onUnhandled);
    try {
      await expect(runAgent({ message: "Why is Dallas high?", history: [] }, { model: hangingModel(), modelId: "mock/slow", context: ctx })).rejects.toThrow(
        /LlmCallError \|\| .*timeout.* \|\| runAgent \|\| 🦉/i,
      );
      await new Promise((r) => setTimeout(r, 50));
      expect(unhandled).toEqual([]);
    } finally {
      process.off("unhandledRejection", onUnhandled);
    }
  });
});

