// Scratch repro (gitignored): a real model step timeout, and where the escaping promise is born.
import { createHook } from "node:async_hooks";
import { createOpenRouter } from "@openrouter/ai-sdk-provider";
import { describe, expect, it, vi } from "vitest";
import { runAgent } from "../../src/core/agent/runAgent";
import { ctx } from "../../src/core/agent/testFixtures";

vi.mock("../../src/core/agent/config", async (importOriginal) => {
  const original = await importOriginal<typeof import("../../src/core/agent/config")>();
  return { ...original, AGENT_LIMITS: { ...original.AGENT_LIMITS, timeouts: { totalMs: 10_000, stepMs: Number(process.env.STEP_MS ?? 1500), toolMs: 5_000 } } };
});

const born = new WeakMap<object, string>();
const hook = createHook({
  init(_id, type, _trigger, resource) {
    if (type === "PROMISE") born.set(resource as object, new Error().stack ?? "");
  },
});

describe("real model step timeout", () => {
  it("no unhandled rejection", async () => {
    process.loadEnvFile(".env.local");
    const unhandled: unknown[] = [];
    const onUnhandled = (reason: unknown, promise: Promise<unknown>) => {
      unhandled.push(reason);
      const stack = (born.get(promise) ?? "?")
        .split("\n")
        .filter((l) => /node_modules|src\//.test(l) && !/async_hooks|vitest|@vitest/.test(l))
        .slice(0, 14)
        .join("\n");
      console.log(`UNHANDLED PROMISE CREATED AT:\n${stack}`);
    };
    process.on("unhandledRejection", onUnhandled);
    const model = createOpenRouter({ apiKey: process.env.OPENROUTER_API_KEY! }).chat(process.env.REPRO_MODEL ?? "anthropic/claude-haiku-5.5");
    hook.enable();
    let outcome = "resolved";
    try {
      await runAgent({ message: "Why is Dallas high?", history: [] }, { model, modelId: "real", context: ctx });
    } catch (e) {
      outcome = `rejected: ${e instanceof Error ? e.message.slice(0, 160) : String(e)}`;
    }
    console.log("OUTCOME:", outcome);
    await new Promise((r) => setTimeout(r, 3000));
    hook.disable();
    process.off("unhandledRejection", onUnhandled);
    expect(unhandled).toEqual([]);
  }, 30_000);
});

