// Collects the result JSON paths from re-grade logs and summarizes judge reliability.
const fs = require("fs");
const dir = process.argv[2];
const out = [];
for (const f of fs.readdirSync(dir).filter((f) => f.endsWith(".log"))) {
  const t = fs.readFileSync(`${dir}/${f}`, "utf8");
  const m = t.match(/^Report: (.+)\.md\s*$/m);
  if (m) out.push(m[1].split("\\").join("/") + ".json");
  else console.log(`NO REPORT: ${f}`);
  const selfTest = (t.match(/self-test:.*$/m) || [""])[0];
  const contradicting = (t.match(/(\d+) self-contradicting/) || [])[1] || "0";
  console.log(`${f.split("__")[0].padEnd(30)} ${f.split("__")[1].slice(25, 60).padEnd(36)} ${selfTest.slice(0, 70)} · contradicting ${contradicting}`);
}
fs.writeFileSync(`${dir}/files.txt`, out.join("\n"));
console.log(`files: ${out.length}`);

