/** Runs one turn (answerQuestion with real or fake deps). */
export type TurnRunner = (
  request: ChatRequest,
  callbacks: AgentCallbacks & { onSession?: (sessionId: string) => void },
) => Promise<QuestionResult>;

/** Shown while the answer is being re-checked after a failed validation. */
const RETRY_MESSAGE = "Double-checking my numbers against the data…";

/**
 * Builds the streaming response body for one chat turn.
 * @param request - the validated request.
 * @param run - runs the turn and reports progress through callbacks.
 * @returns a stream of UI message chunks.
 */
export function buildChatStream(request: ChatRequest, run: TurnRunner) {
  return createUIMessageStream<SneakoscopeUIMessage>({
    execute: async ({ writer }) => {
      writer.write({ type: "start" });
      const pending = new Map<string, { id: string; label: string }[]>(); // tool name → running calls (FIFO)
      let callCount = 0;
      let textId: string | null = null;
      let attempt = 0;

      const endText = () => {
        if (textId) writer.write({ type: "text-end", id: textId });
        textId = null;
      };

      try {
        const result = await run(request, {
          onSession: (sessionId) => writer.write({ type: "data-session", id: "session", data: { sessionId } }),
          onToolStart: (tool, input) => {
            const call = { id: `progress-${++callCount}`, label: progressLabel(tool, input) };
            pending.set(tool, [...(pending.get(tool) ?? []), call]);
            writer.write({ type: "data-progress", id: call.id, data: { tool, label: call.label, status: "running" } });
          },
          onToolEnd: (tool, output) => {
            const call = pending.get(tool)?.shift();
            if (!call) return;
            const failed = !!output && typeof output === "object" && "error" in output;
            writer.write({ type: "data-progress", id: call.id, data: { tool, label: call.label, status: failed ? "failed" : "done" } });
          },
          onAnswerDelta: (delta) => {
            if (!textId) {
              textId = `answer-${attempt}`;
              writer.write({ type: "text-start", id: textId });
            }
            writer.write({ type: "text-delta", id: textId, delta });
          },
          onRetry: () => {
            endText();
            attempt++;
            writer.write({ type: "data-retry", id: `retry-${attempt}`, data: { message: RETRY_MESSAGE } });
          },
        });
        endText();
        writer.write({ type: "data-answer", id: "answer", data: result.answer });
      } catch (error) {
        endText();
        console.error(
          formatBoundaryMessage({
            name: error instanceof Error ? error.name : "UnknownError",
            message: describeUnknownError(error),
            functionName: "buildChatStream",
            boundary: "apiRoute",
          }),
        );
        const { code, message, hint, retryable } = toUserError(error);
        writer.write({ type: "data-error", id: "error", data: { code, message, hint, retryable } });
      }
      writer.write({ type: "finish" });
    },
    onError: (error) => toUserError(error).message,
  });
}
====

/**
 * Runs the ingest, then scores all hubs with the ingest's run id. Scoring runs
 * even if some hubs failed to ingest — they are scored on the data they already have.
 * @param options - ingest options.
 * @param deps - ingest and scoring dependencies.
 * @returns both summaries.
 */
export async function runIngestThenScore(
  options: IngestOptions,
  deps: { ingest: IngestDeps; scoring: ScoringDeps },
): Promise<PipelineSummary> {
  const ingest = await runIngest(options, deps.ingest);
  const scoring = await runScoring({ trigger: "ingest", runId: ingest.runId }, deps.scoring);
  return { ingest, scoring };
}
====
const round1 = (value: number) => Math.round(value * 10) / 10;

/**
 * Scores one hub.
 * @param observed - observed-weather signals for the window (null if none).
 * @param fema - FEMA county signals (null if no record).
 * @returns the full, explainable score.
 */
export function scoreHub(observed: ObservedSignals | null, fema: FemaSignals | null): HubScore {
  const hazards = computeHazardScores(observed, fema);
  // The overall is computed from the published (rounded) hazard scores, so the numbers the agent shows add up.
  const scores = Object.fromEntries(HAZARDS.map((h) => [h, hazards[h].score])) as Record<Hazard, number>;
  const overall = computeOverall(scores);
  const overallScore = round1(overall.overallScore);
  return {
    scoringVersion: SCORING_VERSION,
    overallScore,
    weightedAverage: round1(overall.weightedAverage),
    riskLevel: riskLevelFor(overallScore),
    topHazard: overall.topHazard,
    confidence: weakestConfidence(HAZARDS.map((h) => hazards[h].confidence)),
    hazards,
  };
}

/**
 * Computes the overall score from hazard scores.
 * @param scores - 0–100 score per hazard.
 * @returns overall score, weighted average and top hazard.
 */
export function computeOverall(scores: Record<Hazard, number>): OverallResult {
  const weightedAverage = HAZARDS.reduce((sum, hazard) => sum + HAZARD_WEIGHTS[hazard] * scores[hazard], 0);
  // HAZARDS is in weight order, so a strict ">" keeps the heavier hazard on ties.
  const topHazard = HAZARDS.reduce((top, hazard) => (scores[hazard] > scores[top] ? hazard : top), HAZARDS[0]);
  const overallScore = OVERALL_MIX.weightedAverage * weightedAverage + OVERALL_MIX.worstHazard * scores[topHazard];
  return { overallScore, weightedAverage, topHazard };
}

/**
 * Risk level for an overall score, using the score rounded to a whole number:
 * Low 0–33, Medium 34–66, High 67–100.
 * @param score - 0–100.
 * @returns the level.
 */
export function riskLevelFor(score: number): RiskLevel {
  const rounded = Math.round(score);
  if (rounded >= RISK_LEVEL_CUTOFFS.highFrom) return "high";
  if (rounded >= RISK_LEVEL_CUTOFFS.mediumFrom) return "medium";
  return "low";
}

