3388:  "content": "# 🦉 The Daily Prophet

A weather risk intelligence agent for a logistics company's US distribution hubs.
Analysts chat with it to find out which hubs are most exposed to severe weather, compare hubs,
and understand *why* a hub is risky, to help decide where to invest in resilience upgrades.

> 🚧 Work in progress. Built step by step. See [docs/plan.md](docs/plan.md).

## Docs
- [Plan](docs/plan.md): architecture, tables, steps
- [Decision log](docs/decisions.md): every choice and why
- [Assumptions, uncertainty & scope](docs/assumptions.md)
- [Design](docs/design.md)
- [AI session log](docs/session/): the full conversation with the coding agent

## Run locally
Requirements: Node 22+, a Supabase project.

```bash
npm install
cp .env.example .env.local     # then fill in the values (see comments in the file)
npm run db:check               # verifies the database connection: lists the hubs
npm run dev                    # http://localhost:3000
```

## Scripts
| Command | What it does |
|---|---|
| `npm run dev` | Start the app locally |
| `npm test` | Unit tests (Vitest) |
| `npm run typecheck` | TypeScript check |
| `npm run lint` | ESLint (includes the rule keeping `src/core` free of Next.js) |
| `npm run db:check` | Connect to Supabase and list hubs per region |
| `npm run session:export -- <file.jsonl>` | Export the AI session log to `docs/session/` (scrubbed) |

## Database
SQL migrations live in [supabase/migrations/](supabase/migrations/). Apply them in order to a fresh
Supabase project (SQL editor or Supabase CLI). The second migration seeds the 36 hubs.

## Data attribution
Weather data by [Open-Meteo.com](https://open-meteo.com/) (CC BY 4.0). Hazard data: FEMA National Risk Index.
"
13022:  "content": "/**
 * @module core/agent/answerSchema
 *
 * The structured-output contract between the LLM and our code (requirement 7).
 * - `llmAnswerSchema`: what the MODEL must produce (validated by the AI SDK with Zod).
 * - `FinalAnswer`: what our CODE returns after checking and correcting it
 *   (premise verdict, confidence, disclaimer and caveats are set by code).
 */
import { z } from "zod";
import { CONFIDENCE_LEVELS, HAZARDS, RISK_LEVELS, type Confidence, type Hazard, type RiskLevel } from "../scoring/types";

/** A number the answer relies on — it must come from a tool result (G3). */
export const dataUsedSchema = z.object({
  hubId: z.string().nullable().describe("Hub id the number is about, or null if not hub-specific."),
  label: z.string().describe('What the number is, e.g. "overall risk score", "% of days with measurable snow in 2025".'),
  value: z.number().describe("The number EXACTLY as a tool returned it. Never compute or convert numbers yourself."),
  unit: z.string().describe('Unit as the tool gave it, e.g. "score 0-100", "%", "days/yr".'),
});

/** The claim a question makes about a hub's risk level, extracted by the model (G5). */
export const premiseClaimSchema = z.object({
  hubId: z.string(),
  hazard: z.enum(HAZARDS).nullable().describe("The hazard the claim is about, or null for the overall risk."),
  claimedLevel: z.enum(RISK_LEVELS).describe("The level the question assumes, e.g. 'Why is Dallas high?' → high."),
});

/** What the model must return as its final answer. */
export const llmAnswerSchema = z.object({
  answer: z.string().describe("The answer for the analyst, in Markdown. Plain language. Explain WHY using the tool numbers."),
  outOfScope: z.boolean().describe("True when the question is not about weather risk for our hubs."),
  hubsMentioned: z.array(z.string()).describe("Ids of the hubs the answer talks about (must come from tool results)."),
  dataUsed: z.array(dataUsedSchema).describe("Every number the answer relies on, copied from tool results."),
  premiseClaim: premiseClaimSchema
    .nullable()
    .describe("If the question ASSUMES a hub's risk level (e.g. 'why is X high?'), extract that claim; otherwise null."),
  confidence: z.enum(CONFIDENCE_LEVELS).nullable().describe("Your best guess; code recomputes it from the data."),
  assumptions: z.array(z.string())
16797:  "content": "/**
 * POST /api/chat — the agent's API (requirement 6). The UI calls this, never the LLM.
 * Body: { sessionId: uuid | null, message: string, units: "us" | "metric" }.
 * Streams the AI SDK chat protocol: session, progress, answer text, validated answer (A1).
 */
import { createUIMessageStreamResponse } from "ai";
import { answerQuestion } from "@/core/agent/answerQuestion";
import { createAnswerQuestionDeps } from "@/core/agent/createAnswerQuestionDeps";
import { buildChatStream, chatRequestSchema } from "@/core/api/chatStream";
import { failure, requireSiteAuth } from "../_lib/http";

/** Upper bound for one turn (the agent's own total timeout is 60 s; a validation retry may follow). */
export const maxDuration = 120;

/**
 * Answers one chat message as a stream.
 * @param request - the HTTP request.
 * @returns the streaming response, or a friendly JSON error before streaming starts.
 */
export async function POST(request: Request): Promise<Response> {
  try {
    const denied = requireSiteAuth(request);
    if (denied) return denied;
    const body = chatRequestSchema.parse(await request.json());
    const deps = createAnswerQuestionDeps();
    const stream = buildChatStream(body, (req, callbacks) => answerQuestion(req, deps, callbacks));
    return createUIMessageStreamResponse({ stream, headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return failure(error, "POST /api/chat");
  }
}
"
19196:  "content": ""use client";
/**
 * The whole app (U1): side nav (this browser's chats) · chat · widgets.
 * Talks ONLY to our API (requirement 6): /api/chat (streaming), /api/widgets,
 * /api/chat/sessions and /api/chat/history.
 */
import { useChat } from "@ai-sdk/react";
import { DefaultChatTransport } from "ai";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { ProphetDataParts, ProphetUIMessage } from "@/core/api/chatStream";
import type { TranscriptTurn } from "@/core/db/chatTranscript";
import { userError } from "@/core/errors/userErrors";
import type { UnitSystem } from "@/core/utils/units";
import type { WidgetsData } from "@/core/widgets/widgetsData";
import { loadSessionIds, loadUnits, rememberSession, saveUnits } from "../_lib/storage";
import { AssistantMessage } from "./answer/AssistantMessage";
import { ErrorCard } from "./answer/ErrorCard";
import { Composer } from "./Composer";
import { EmptyState } from "./EmptyState";
import { Footer } from "./Footer";
import { Header } from "./Header";
import { SideNav } from "./SideNav";
import { WidgetsRail } from "./WidgetsRail";

/** Text of a user message. */
function textOf(message: ProphetUIMessage | undefined): string {
  return message?.parts.map((part) => (part.type === "text" ? part.text : "")).join("") ?? "";
}

/** Friendly error from a failed request (the API answers with `{ error: {...} }`). */
function requestError(error: Error): ProphetDataParts["error"] {
  try {
    const parsed = JSON.parse(error.message) as { error?: ProphetDataParts["error"] };
    if (parsed.error?.message) return parsed.error;
  } catch {
    // not JSON — e.g. the network dropped
  }
  const { code, message, hint, retryable } = userError("internal_error");
  return { code, message, hint, retryable };
}

/** Rebuilds UI messages from a saved transcript (validated answers, as they were shown). */
function messagesFromTurns(turns: TranscriptTurn[]): ProphetUIMessage[] {
  return turns.flatMap((turn, index) => [
    { id: `history-user-${index}`, role: "user" as const, parts: [{ type: "text" as const, text: turn.question }] },
    {
      id: `history-answer-${index}`,
      role: "assistant" as const,
      parts: [{ type: "data-answer" as const, id: "answer", data: turn.answer }],
    },
20872:  "content": "## Summary

Step 6 of [the plan](docs/plan.md): **the chat UI.** Dark glass with Roboto. It talks **only** to our API (requirement 6). Visuals are chosen by code from the tool results, and only where they show something the text can't.

![A conversation: Dallas score breakdown, Miami vs Houston grid, Denver seasonality, Seattle premise correction](https://raw.githubusercontent.com/yardenfarag/Home-Assignment-Moveo/step-6-ui/docs/screenshots/desktop-conversation.png)

```text
<ProphetApp>  (src/app/_components/ProphetApp.tsx, "use client")
  useSyncExternalStore(units, sessionIds)        # this browser's settings + chat ids (localStorage)
  useChat(DefaultChatTransport → POST /api/chat)  # body: { sessionId, message, units } per sendMessage
  <Header>       wordmark · freshness · US/Metric · New chat
  <SideNav>      GET /api/chat/sessions?ids=…   → open: GET /api/chat/history?sessionId=…
  <main>
    <EmptyState>     the brief's four questions
    <AssistantMessage>
      streaming:  <ProgressList> (data-progress) · text deltas · "Double-checking…" (data-retry)
      final:      <FinalAnswerCard> (data-answer)
                    <PremiseBanner> · <Markdown> · pickVisuals(answer) → visuals
                    <RecommendationBox> · confidence · <Disclosure>×2 · follow-up chips
      failed:     <ErrorCard> (data-error: message + hint + Try again)
    <Composer>   Enter sends · Shift+Enter newline · Stop
  <WidgetsRail>  GET /api/widgets — phone: swipe strip · tablet: row · desktop: column
  <Footer>       Open-Meteo (CC BY 4.0) · FEMA attribution
```

| Visual (U3b) | Shows what text can't | Source |
|---|---|---|
| **Score breakdown** | *where* a hub's score comes from: each hazard's points + the worst-hazard boost | `explain_hub_score.formula.contributions` |
| **Comparison grid** | hubs × hazards at a glance, level color **and** text | `compare_hubs` |
| **Seasonality strip** | *when* hazard days happen (month by month) | `get_weather_stat.byMonth` |
| **Ranked list** | the ranking itself (no chart) | `rank_hubs` |

## Decisions (D80–D88, round U1–U8)

| # | Decision |
|---|---|
| D80 | Layout: chats · chat · overview. Phone swipe strip, tablet row, desktop column |
| D81 | Answer card anatomy. Only the **validated** answer gets the data panel |
| D82 | **Visuals only
